from typing import List


def getMaximumSumOfStrengths(arr: List[int]) -> int:
    n = len(arr)
    dp = [0] * (n + 1)  # dp[i]: best sum over arr[0..i-1]
    for i in range(1, n + 1):
        dp[i] = dp[i - 1] + arr[i - 1] * i
        if i >= 2:
            dp[i] = max(dp[i], dp[i - 2] + arr[i - 2] * i + arr[i - 1] * (i - 1))
    return dp[n]
